"""Built-in report templates and the built-in findings library for the Reporting feature.
All text uses only the rich-HTML subset of the reporting contract and the {{client}}, {{engagement}}, {{start_date}}, {{end_date}},
{{company}}, {{report_date}} placeholders, which the exporter fills in from the report's meta and branding."""
def _p(*paras):return "".join(f"<p>{t}</p>" for t in paras)
def _ul(*items):return "<ul>"+"".join(f"<li>{t}</li>" for t in items)+"</ul>"
def _ol(*items):return "<ol>"+"".join(f"<li>{t}</li>" for t in items)+"</ol>"
def _table(head,rows):
    return "<table><thead><tr>"+"".join(f"<th>{h}</th>" for h in head)+"</tr></thead><tbody>"+"".join("<tr>"+"".join(f"<td>{c}</td>" for c in r)+"</tr>" for r in rows)+"</tbody></table>"
SEVERITY_TABLE=_table(("Rating","CVSS v3.1","Definition"),(
    ("<strong>Critical</strong>","9.0 - 10.0","Exploitation is straightforward and leads to full compromise of the system, its data or the wider environment, usually without authentication. Remediate immediately."),
    ("<strong>High</strong>","7.0 - 8.9","Exploitation gives significant access to sensitive data or functionality, or a foothold that makes further compromise likely. Remediate as a priority, typically within 30 days."),
    ("<strong>Medium</strong>","4.0 - 6.9","Exploitation needs specific conditions, user interaction or existing access, or the impact is limited. Remediate within the normal change cycle, typically within 90 days."),
    ("<strong>Low</strong>","0.1 - 3.9","Limited direct impact. The issue weakens defence in depth or helps an attacker in combination with other weaknesses. Remediate as part of routine maintenance."),
    ("<strong>Informational</strong>","0.0","No direct security impact. Observations, good-practice deviations and hardening opportunities recorded for completeness."),
))
SEVERITY_TEXT=_p("Each finding is given a severity rating that reflects the likelihood of exploitation and the impact on the confidentiality, integrity and availability of the affected asset. Where applicable a Common Vulnerability Scoring System (CVSS) v3.1 base vector and score are provided. The rating also takes the context of the environment into account, so it may differ from the CVSS score alone.")+SEVERITY_TABLE
DISCLAIMER=_p(
    "This assessment was performed within a fixed time frame and against the agreed scope only. A penetration test is a point-in-time exercise: it reflects the state of the environment between {{start_date}} and {{end_date}} and cannot guarantee that every vulnerability has been identified. Changes made to the systems after the testing window, and newly disclosed vulnerabilities, are not covered by this report.",
    "The findings and recommendations are provided in good faith and are based on the information available to {{company}} during the engagement. {{company}} does not accept liability for losses arising from the use of this report, or for security incidents affecting the systems described in it.",
    "This document contains sensitive information about the security posture of {{client}}. It is intended solely for the named recipients and should be stored, transmitted and destroyed in line with its classification.")
def _exec_summary(kind,goal):
    return _p(
        f"{{{{company}}}} was engaged by {{{{client}}}} to perform {kind} ({{{{engagement}}}}). Testing took place between {{{{start_date}}}} and {{{{end_date}}}}. {goal}",
        "This section summarises the results for a non-technical audience. Full technical detail, evidence and remediation guidance for every issue are provided in the Detailed Findings section.")+"<h4>Overall assessment</h4>"+_p(
        "[State the overall security posture in one or two sentences: for example whether an external attacker could obtain access to sensitive data, and how much effort that required.]")+"<h4>Key findings</h4>"+_ul(
        "[Most significant finding, described in business terms, and what it allowed the testers to do.]",
        "[Second most significant finding.]",
        "[Recurring theme or root cause, for example patch management, access control or credential hygiene.]")+"<h4>Strengths observed</h4>"+_ul(
        "[Controls that worked well and slowed or prevented attacks.]")+"<h4>Strategic recommendations</h4>"+_ul(
        "[Highest-priority action for the next 30 days.]",
        "[Medium-term improvement that addresses the root cause.]",
        "[Process or governance recommendation, such as a retest after remediation.]")
def _scope(extra_rules=()):
    return _p(
        "The scope of the engagement was agreed with {{client}} before testing started. The in-scope and out-of-scope assets recorded for this report are listed below, followed by the rules of engagement that applied.")+"<h4>Rules of engagement</h4>"+_ul(
        "Testing was performed between {{start_date}} and {{end_date}}, during the hours agreed with {{client}}.",
        "Only the assets listed as in scope were tested. Any system discovered outside the agreed scope was not attacked and was reported to the client contact.",
        "Denial-of-service attacks and actions likely to degrade or interrupt production services were excluded unless explicitly authorised.",
        "Critical and high-severity issues were reported to the client contact as soon as they were confirmed, without waiting for this report.",
        "Data accessed during testing was handled as confidential, limited to the minimum needed to demonstrate impact, and removed from tester systems at the end of the engagement.",
        *extra_rules)+"<h4>Limitations</h4>"+_p(
        "[Record anything that restricted testing: unavailable systems, accounts that were not provided, time constraints, blocking by security controls, or parts of the scope that could not be covered.]")
_PHASES_NOTE=_p("All testing was performed manually by experienced consultants and supported by automated tooling. Automated results were verified by hand before being reported, to remove false positives and to establish real-world impact.")
