def _s(kind,title,content="",hidden=False):return {"kind":kind,"title":title,"content":content,"hidden":bool(hidden)}
def _standard(exec_kind,exec_goal,methodology,extra_rules=(),extra=(),timeline_hidden=True):
    out=[
        _s("executive_summary","Executive Summary",_exec_summary(exec_kind,exec_goal)),
        _s("scope","Scope and Rules of Engagement",_scope(extra_rules)),
        _s("methodology","Methodology",methodology),
    ]
    out+=list(extra)
    out+=[
        _s("findings_summary","Findings Summary",_FINDINGS_SUMMARY),
        _s("findings","Detailed Findings",_FINDINGS),
        _s("remediation_roadmap","Remediation Roadmap",_ROADMAP),
        _s("conclusion","Conclusion",_CONCLUSION),
        _s("document_control","Document Control",_DOC_CONTROL),
        _s("appendix_tools","Appendix A - Tools Used",_APP_TOOLS),
        _s("appendix_commands","Appendix B - Commands Run",_APP_COMMANDS),
        _s("appendix_evidence","Appendix C - Evidence",_APP_EVIDENCE),
        _s("appendix_timeline","Appendix D - Testing Timeline",_APP_TIMELINE,timeline_hidden),
    ]
    return out
_RT_NARRATIVE=_p("This section tells the story of the engagement in chronological order, from initial reconnaissance to the actions taken on each objective. Each step lists the technique used (with its MITRE ATT&amp;CK identifier), the outcome, and whether the activity was prevented, detected or responded to.")+_table(("Date / time (UTC)","Phase","Activity","ATT&amp;CK technique","Outcome","Detected"),(("[Date]","[Phase]","[What the red team did]","[T0000]","[Result]","[Yes / No / Partially]"),))
