def _lib(uid,title,category,severity,vector,cwe,owasp,description,impact,remediation,steps="",references=(),tags=()):
    return {"uid":"builtin-"+uid,"title":title,"category":category,"severity":severity,"cvss_vector":("CVSS:3.1/"+vector) if vector else "","cwe":cwe,"owasp":owasp,"description":description,"impact":impact,"remediation":remediation,"steps":steps,"references":list(references),"tags":list(tags),"likelihood":"","retest_notes":"","source":{"kind":"library","ref":"builtin"}}
_STEPS_HINT=lambda *s:_ol(*s)
